std::string Darwin::ComputeEffectiveClangTriple(const ArgList &Args,
                                                BoundArch BA,
                                                types::ID InputType) const {
  llvm::Triple Triple(ComputeLLVMTriple(Args, BA, InputType));

  // If the target isn't initialized (e.g., an unknown Darwin platform, return
  // the default triple). Note: we intentionally do NOT call
  // ensureTargetInitialized() here because this method is called before
  // AddDeploymentTarget() in some code paths (e.g. -print-libgcc-file-name),
  // and lazy init with version 0.0.0 would conflict with the real version
  // that AddDeploymentTarget() later sets via setTarget().
  if (!isTargetInitialized())
    return Triple.getTriple();

  SmallString<16> Str;
  if (isTargetWatchOSBased())
    Str += "watchos";
  else if (isTargetTvOSBased())
    Str += "tvos";
  else if (isTargetDriverKit())
    Str += "driverkit";
  else if (isTargetIOSBased() || isTargetMacCatalyst())
    Str += "ios";
  else if (isTargetXROS())
    Str += llvm::Triple::getOSTypeName(llvm::Triple::XROS);
    // accordingly.
    MSVT = VersionTuple(19, 33);
  }
  return MSVT;
}

std::string
MSVCToolChain::ComputeEffectiveClangTriple(const ArgList &Args, BoundArch BA,
                                           types::ID InputType) const {
  // The MSVC version doesn't care about the architecture, even though it
  // may look at the triple internally.
  VersionTuple MSVT = computeMSVCVersion(/*D=*/nullptr, Args);
  MSVT = VersionTuple(MSVT.getMajor(), MSVT.getMinor().value_or(0),
                      MSVT.getSubminor().value_or(0));

  // For the rest of the triple, however, a computed architecture name may
  // be needed.
  llvm::Triple Triple(
      ToolChain::ComputeEffectiveClangTriple(Args, BA, InputType));
  if (Triple.getEnvironment() == llvm::Triple::MSVC) {
    StringRef ObjFmt = Triple.getEnvironmentName().split('-').second;
    if (ObjFmt.empty())
      Triple.setEnvironmentName((Twine("msvc") + MSVT.getAsString()).str());
    else
      Triple.setEnvironmentName(
          (Twine("msvc") + MSVT.getAsString() + Twine('-') + ObjFmt).str());
  }
  return Triple.getTriple();
}

