  checkAMDGPUCodeObjectVersion(D, Args);

  if (Triple.getOS() == llvm::Triple::AMDHSA &&
      Triple.getEnvironment() != llvm::Triple::LLVM)
    RocmInstallation->detectDeviceLibrary();

  if (HostTC)
    getProgramPaths().push_back(getDriver().Dir);
}

